import{c as a,Q as t,j as o,m as r}from"./chunks/framework.BPKcPtvA.js";const n="/images/wordpress-language-setting.png",l="/images/loco-translate.png",s="/images/poedit.png",f=JSON.parse('{"title":"Theme Translation","description":"","frontmatter":{},"headers":[],"relativePath":"how-to/translate-theme.md","filePath":"how-to/translate-theme.md"}'),i={name:"how-to/translate-theme.md"};function d(c,e,g,p,h,u){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="theme-translation" tabindex="-1">Theme Translation <a class="header-anchor" href="#theme-translation" aria-label="Permalink to &quot;Theme Translation&quot;">​</a></h1><p>In each of our themes and plugins you will find a <strong>languages</strong> folder containing a <code>themename.pot</code> or <code>pluginname.pot</code> file.</p><p>A <code>.pot</code> file is a template containing all translatable strings. You can use it to translate your theme or plugin into any language and generate the <code>.po</code> and <code>.mo</code> files that WordPress uses to display the translation.</p><h2 id="set-your-language-in-wordpress" tabindex="-1">Set Your Language in WordPress <a class="header-anchor" href="#set-your-language-in-wordpress" aria-label="Permalink to &quot;Set Your Language in WordPress&quot;">​</a></h2><p>Before translating, set your site language under <strong>Settings &gt; General</strong> and select your language at the bottom of the page.</p><p><img src="'+n+'" alt="WordPress Language Setting"></p><h2 id="translate-with-loco-translate-recommended" tabindex="-1">Translate with Loco Translate (Recommended) <a class="header-anchor" href="#translate-with-loco-translate-recommended" aria-label="Permalink to &quot;Translate with Loco Translate (Recommended)&quot;">​</a></h2><p><a href="https://wordpress.org/plugins/loco-translate/" target="_blank" rel="noreferrer">Loco Translate</a> allows you to translate all strings directly in your WordPress admin panel.</p><ol><li>Install and activate Loco Translate.</li><li>Navigate to <strong>Loco Translate &gt; Themes</strong> (or Plugins) and select the theme or plugin to translate.</li><li>In the Overview tab, click <strong>New language</strong> or select an existing language to continue.</li><li>Select each string and fill in the Translation field. Save after each session.</li></ol><p><img src="'+l+'" alt="Loco Translate"></p><blockquote><p>If you create a new translation or improve an existing one, please send your <code>.po</code> and <code>.mo</code> files to <strong><a href="mailto:help@wolfthemes.com" target="_blank" rel="noreferrer">help@wolfthemes.com</a></strong> — it is much appreciated!</p></blockquote><h2 id="translate-with-poedit" tabindex="-1">Translate with Poedit <a class="header-anchor" href="#translate-with-poedit" aria-label="Permalink to &quot;Translate with Poedit&quot;">​</a></h2><p><a href="http://www.poedit.net/download.php" target="_blank" rel="noreferrer">Poedit</a> is a desktop app for translating from the <code>.pot</code> file. You will need to upload the files manually to your server after each update.</p><ol><li>Open Poedit and go to <strong>File &gt; New from POT file</strong>.</li><li>Select the <code>.pot</code> file from your theme or plugin&#39;s <code>languages</code> folder.</li><li>Translate each string and save.</li></ol><p><img src="'+s+'" alt="Poedit"></p><p>Name your translation files using the correct language code:</p><ul><li>French: <code>fr_FR.po</code> and <code>fr_FR.mo</code></li><li>German: <code>de_DE.po</code> and <code>de_DE.mo</code></li></ul><p>For plugins, prefix with the plugin slug: <code>wolf-plugin-slug-fr_FR.po</code> and <code>wolf-plugin-slug-fr_FR.mo</code>.</p><p>Browse the <a href="https://make.wordpress.org/polyglots/teams/" target="_blank" rel="noreferrer">WordPress language code list</a> to find the correct code for your language.</p><h2 id="multi-language-sites" tabindex="-1">Multi-language Sites <a class="header-anchor" href="#multi-language-sites" aria-label="Permalink to &quot;Multi-language Sites&quot;">​</a></h2><p>For multi-language websites, you can use the <a href="http://wpml.org/" target="_blank" rel="noreferrer">WPML</a> plugin (premium).</p>',21)])])}const _=a(i,[["render",d]]);export{f as __pageData,_ as default};
